Add-Type -AssemblyName System.Drawing; $img = [System.Drawing.Image]::FromFile('D:\SORA\landing\public\sora-logo.png'); $bmp = new-object System.Drawing.Bitmap($img); $colors = @{}; for ($x = 0; $x -lt $bmp.Width; $x += 5) { for ($y = 0; $y -lt $bmp.Height; $y += 5) { $c = $bmp.GetPixel($x, $y); if ($c.A -gt 100 -and ($c.R -lt 250 -or $c.G -lt 250 -or $c.B -lt 250)) { $hex = '#{0:X2}{1:X2}{2:X2}' -f $c.R, $c.G, $c.B; if (-not $colors.ContainsKey($hex)) { $colors[$hex] = 0 }; $colors[$hex]++ } } }; $colors.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 5
